29	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
30	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
31	/// epic's UX constraints; the portrait lock itself lives in
32	/// `ios/Runner/Info.plist`, Story 1.6).
33	///
34	/// Story 1.6 scope: the ad-hoc `StreamBuilder`/`Navigator.push` shell
35	/// Stories 1.3-1.5 built this on top of is replaced by the one real
36	/// `go_router` (`core/navigation/app_router.dart`) plus its
37	/// `ExpiryOverlayHost` wrapper — [restoreSession] still fires once at boot
38	/// here (unchanged from Story 1.4), but every screen transition and the
39	/// expiry overlay's own "Entrar novamente" now go through that router
40	/// instead of an imperative `Navigator`.
41	class CerneApp extends StatefulWidget {
42	  const CerneApp({super.key});
43	
44	  @override
45	  State<CerneApp> createState() => _CerneAppState();
46	}
47	
48	class _CerneAppState extends State<CerneApp> {
49	  late final SessionRepository _sessionRepository;
50	  late final VaultRepository _vaultRepository;
51	  late final GoRouter _router;
52	
53	  // Created here (not left for `GoRouter` to generate internally) and
54	  // passed to both `buildAppRouter` and `ExpiryOverlayHost` below, so the
55	  // latter can reach the Navigator's own `BuildContext` through this
56	  // public, documented key instead of reaching into `GoRouter`'s internal
57	  // `routerDelegate`.
58	  final GlobalKey<NavigatorState> _navigatorKey = GlobalKey<NavigatorState>(
59	    debugLabel: 'root',
60	  );
61	
62	  @override
63	  void initState() {
64	    super.initState();
65	    _sessionRepository = sl<SessionRepository>();
66	    _vaultRepository = sl<VaultRepository>();
67	    _router = buildAppRouter(
68	      vaultRepository: _vaultRepository,
69	      sessionRepository: _sessionRepository,
70	      navigatorKey: _navigatorKey,
71	    );
72	    // Fire-and-forget: the outcome reaches the UI through
73	    // `SessionRepository.currentStatus`/`statusStream` (which the router's
74	    // `redirect`/`refreshListenable` already watch), not through this
75	    // call's return value. `restoreSession()` already maps every internal
76	    // failure to `Left`/an `unauthenticated` emission and never throws.
77	    // This `catchError` is NOT a UI recovery path — its handler's return
78	    // value is discarded by `unawaited` and never reaches `statusStream`.
79	    // It exists purely so a future regression that broke the "never
80	    // throws" contract above would surface as a logged message instead of
81	    // an unhandled zone exception.
82	    unawaited(
83	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
84	    );
85	  }
86	
87	  @override
88	  void dispose() {
89	    _router.dispose();
90	    super.dispose();
91	  }
92	
93	  // `catchError`'s handler must still complete the Future with a value of
94	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
95	  // handler would try to complete it with `null`, which isn't assignable
96	  // to that non-nullable type and would itself throw.
97	  static Either<Failure, Unit> _asUnauthenticated(
98	    Object error,
99	    StackTrace stackTrace,
100	  ) {
101	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
102	    return left(Failure.malformedResponse(message: error.toString()));
103	  }
104	
105	  @override
106	  Widget build(BuildContext context) {
107	    return MaterialApp.router(
108	      debugShowCheckedModeBanner: false,
109	      routerConfig: _router,
110	      builder: (context, child) => ExpiryOverlayHost(
111	        sessionRepository: _sessionRepository,
112	        router: _router,
113	        navigatorKey: _navigatorKey,
114	        child: child!,
115	      ),
116	    );
117	  }
118	}
